<template>
    <div class="card"><div class="card-header d-flex justify-content-between align-items-center"><span class="fw-semibold"><i class="bi bi-shield-check me-2"></i>System audit trail</span><button class="btn btn-sm btn-outline-secondary" @click="load">Refresh</button></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Date / time</th><th>User</th><th>Action</th><th>Record</th><th>Changes</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td class="text-nowrap small">{{ new Date(log.created_at).toLocaleString() }}</td><td>{{ log.user?.name || 'System' }}</td><td><span class="badge" :class="log.action === 'deleted' ? 'bg-danger' : log.action === 'updated' ? 'bg-warning text-dark' : 'bg-success'">{{ log.action.replaceAll('_',' ') }}</span></td><td class="small">{{ shortType(log.subject_type) }} #{{ log.subject_id }}</td><td><details><summary class="small text-success">View details</summary><pre class="small bg-body-tertiary p-2 mt-2 mb-0">{{ JSON.stringify({before:log.old_values,after:log.new_values},null,2) }}</pre></details></td></tr><tr v-if="!logs.length"><td colspan="5" class="text-center text-muted py-4">No audit activity recorded yet.</td></tr></tbody></table></div><div class="card-footer d-flex justify-content-between align-items-center"><small class="text-muted">Page {{ page }} · {{ logs.length }} records</small><div class="btn-group btn-group-sm"><button class="btn btn-outline-secondary" :disabled="page<=1" @click="page--;load()">Previous</button><button class="btn btn-outline-secondary" :disabled="!next" @click="page++;load()">Next</button></div></div></div>
</template>
<script setup>
import { onMounted,ref } from 'vue';import api from '../api';
const logs=ref([]),page=ref(1),next=ref(false);function shortType(v){return (v||'').split('\\').pop()||'—';}async function load(){const {data}=await api.get('/audit-logs',{params:{page:page.value,per_page:30}});logs.value=data.data;next.value=!!data.next_page_url;}onMounted(load);
</script>
